extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main_scene", main != null, "La scena principale res://main.tscn deve avviarsi senza errori"):
		return

	var world = instantiate_script("res://world.gd")
	if not check("world_instantiate", world != null, "Lo script res://world.gd deve potersi istanziare senza errori"):
		return

	if not check("has_load_file", has_function(world, "load_file"), "World deve avere il metodo load_file(file_path: String) -> bool"):
		return
	if not check("has_get_room", has_function(world, "get_room"), "World deve avere il metodo get_room(room_id: String) -> Room"):
		return
	if not check("has_get_start_room", has_function(world, "get_start_room"), "World deve avere il metodo get_start_room() -> Room"):
		return

	var loaded = call_if_exists(world, "load_file", ["res://adventure.json"], false)
	if not check("load_adventure", loaded == true, "load_file('res://adventure.json') deve restituire true su un file valido (errore: %s)" % str(get_prop(world, "last_error", ""))):
		return

	var start_room = call_if_exists(world, "get_start_room", [], null)
	if not check("get_start_room", start_room != null, "get_start_room() deve restituire un'istanza di Room"):
		return

	var start_name = get_prop(start_room, "name", "")
	var start_desc = get_prop(start_room, "description", "")
	check("start_room_fields", not str(start_name).is_empty() and not str(start_desc).is_empty(), "La stanza iniziale deve avere 'name' e 'description' non vuoti")

	var rooms_dict = get_prop(world, "rooms", null)
	if check("world_rooms", rooms_dict is Dictionary and rooms_dict.size() >= 4, "World.rooms deve contenere le stanze caricate come Dictionary"):
		var first_key: String = rooms_dict.keys()[0]
		var queried_room = call_if_exists(world, "get_room", [first_key], null)
		check("get_room_valid", queried_room != null and queried_room == rooms_dict[first_key], "get_room('%s') deve restituire la stanza corrispondente" % first_key)

	var ghost_room = call_if_exists(world, "get_room", ["stanza_fantasma_12345"], "not_null")
	check("get_room_invalid", ghost_room == null, "get_room() con un ID inesistente deve restituire null")

	# Test errore: file inesistente
	clear_printed()
	var missing_ok = call_if_exists(world, "load_file", ["res://non_esiste_123.json"], true)
	check("missing_fails", missing_ok == false, "load_file() con un file inesistente deve restituire false")
	var missing_err = get_prop(world, "last_error", "")
	check("missing_error", not str(missing_err).is_empty(), "load_file() con un file inesistente deve valorizzare last_error")

	# Test errore: JSON non valido
	var f_bad_json := FileAccess.open("user://test_bad_syntax.json", FileAccess.WRITE)
	if f_bad_json != null:
		f_bad_json.store_string("{ non e un json valido ")
		f_bad_json.close()
		var bad_syntax_ok = call_if_exists(world, "load_file", ["user://test_bad_syntax.json"], true)
		check("bad_syntax_fails", bad_syntax_ok == false, "load_file() con JSON sintatticamente errato deve restituire false")
		check("bad_syntax_error", not str(get_prop(world, "last_error", "")).is_empty(), "load_file() con JSON non valido deve valorizzare last_error")

	# Test errore: campo mancante
	var f_missing := FileAccess.open("user://test_missing.json", FileAccess.WRITE)
	if f_missing != null:
		var missing_data := {
			"title": "Avventura Incompleta",
			"rooms": {
				"a": {"name": "A", "description": "D", "exits": {}, "items": []}
			}
		}
		f_missing.store_string(JSON.stringify(missing_data))
		f_missing.close()
		var missing_data_ok = call_if_exists(world, "load_file", ["user://test_missing.json"], true)
		check("missing_field_fails", missing_data_ok == false, "load_file() con JSON privo di 'start_room' deve restituire false")
		check("missing_field_error", not str(get_prop(world, "last_error", "")).is_empty(), "load_file() con campi mancanti deve valorizzare last_error")

	# Test errore: uscita verso stanza inesistente
	var f_bad_exit := FileAccess.open("user://test_bad_exit.json", FileAccess.WRITE)
	if f_bad_exit != null:
		var bad_exit_data := {
			"title": "Avventura con Uscita Errata",
			"start_room": "r1",
			"rooms": {
				"r1": {"name": "R1", "description": "D1", "exits": {"north": "stanza_che_non_esiste"}, "items": []}
			}
		}
		f_bad_exit.store_string(JSON.stringify(bad_exit_data))
		f_bad_exit.close()
		var bad_exit_ok = call_if_exists(world, "load_file", ["user://test_bad_exit.json"], true)
		check("bad_exit_fails", bad_exit_ok == false, "load_file() con un'uscita verso una stanza che non esiste deve restituire false")
		check("bad_exit_error", not str(get_prop(world, "last_error", "")).is_empty(), "load_file() con un'uscita errata deve valorizzare last_error")

	# Test caricamento mondo della piattaforma
	var f_custom := FileAccess.open("user://test_custom_world.json", FileAccess.WRITE)
	if f_custom != null:
		var custom_data := {
			"title": "La Torre dei Saggi",
			"start_room": "base",
			"rooms": {
				"base": {
					"name": "Base della Torre",
					"description": "Gradini di pietra salgono verso l'alto.",
					"exits": {"up": "summit"},
					"items": ["pergamena"]
				},
				"summit": {
					"name": "Cima della Torre",
					"description": "Una terrazza ventosa sotto le stelle.",
					"exits": {"down": "base"},
					"items": ["sfera_cristallo"]
				}
			}
		}
		f_custom.store_string(JSON.stringify(custom_data))
		f_custom.close()
		var custom_ok = call_if_exists(world, "load_file", ["user://test_custom_world.json"], false)
		if check("custom_loads", custom_ok == true, "World deve caricare correttamente una nuova avventura valida (errore: %s)" % str(get_prop(world, "last_error", ""))):
			var summit = call_if_exists(world, "get_room", ["summit"], null)
			check("custom_query", summit != null and str(get_prop(summit, "name", "")) == "Cima della Torre", "Interrogando World per la stanza 'summit' si deve ottenere il nome corretto")
			var summit_items = get_prop(summit, "items", [])
			check("custom_items", summit_items is Array and summit_items.has("sfera_cristallo"), "La stanza 'summit' deve contenere 'sfera_cristallo'")

